附录2.3 网格模型概率矩阵计算 
function [P]=Pij(miu, fileName) 
d=xlsread(fileName,3); % 最短路径矩阵 
De=xlsread(fileName,4); % 方向需求矩阵（非对称） 
P=zeros(7); 
theta=0.3; 

for i=1:1:7 
 Qi=De(i,8); 
 for j=1:1:7 
 if (i==j) 
 continue 
 end 
 fuko=exp(theta*(-d(i,j)+miu*Qi)); % 计算分子的值 
 fumu=0; 
 for k=1:1:7 
 fumu=fumu+exp(theta*(-d(i,k)+miu*Qi)); % 计算分母的值 
 end 
 if (fumu~=0) 
 P(i,j)=fuko/fumu; 
 else 
 P(i,j)=0; 
 end 
 end 
end 
%disp(P); 
end

附录2.4 网格模型空驶总里程期望值计算 
function [V]=V0(miu,fileName) 
d=xlsread(fileName,3); 
De=xlsread(fileName,4); 
[P]=Pij(miu,fileName); 
V=0; 
for i=1:1:7 
 Ei=De(8,i); 
 di=0; 
 for j=1:1:7 
 di=di+d(i,j)*P(i,j); 
 end 
 V=V+Ei*di; 
end 
%disp(V); 
end 


